const SENS=[['База: 400 × £16.95',413.29,563.29],['Только цена: 400 × £15.25',6.56,156.56],['Только продажи: 300 × £16.95',-312.53,-162.53],['Налоговый резерв 19% вместо 25%',508.46,658.46],['Пятёрки 240 × £24.99 (гипотеза)',575.31,725.31],['Пятёрки 200 × £21.99 (гипотеза)',-294.45,-144.45]];
const COST=[['Отправка £4.85 × 400',1940.00,'ass'],['Закупка всей партии',1665.00,'seller'],['Комиссии eBay 13.25% + £0.40',1058.35,'ass'],['Бюджет: подготовка, фото, хранение, учёт',750.00,'ass'],['Налоговый резерв 25%',396.56,'ass'],['Реклама 3%',203.40,'ass'],['Резерв претензий 3%',203.40,'ass'],['Время владельца 10 ч × £15',150.00,'ass']];
const gbp=v=>{const n=v<0,a=Math.abs(v).toFixed(2).split('.');return (n?'−':'')+'£'+a[0].replace(/\B(?=(\d{3})+(?!\d))/g,' ')+'.'+a[1]};
