function figCost(){const tot=COST.reduce((a,x)=>a+x[1],0);const pc=v=>(v/tot*86).toFixed(2)+'%';
 return fig('Структура затрат базового сценария','£ за весь горизонт 90 дней · основание: сценарий 400 × £16.95, входы — допущения a1–a9',
 `<div class="ch-stack" role="img" aria-label="Строки базового сценария, лист 4, и неизвестные статьи без сумм">${COST.map((x,i)=>`<i class="ch-s" data-k="${x[2]}" data-i="${i}" style="width:${pc(x[1])}" title="${esc(x[0])}: ${gbp(x[1])}"></i>`).join('')}<i class="ch-s ch-u" style="width:14%" title="Неизвестно: сортировка, сборка троек, фото и листинг"></i></div>
<ul class="ch-lg">${COST.map((x,i)=>`<li><i class="ch-sw" data-k="${x[2]}" data-i="${i}" aria-hidden="true"></i><span>${esc(x[0])}</span><b class="n">${gbp(x[1])}</b></li>`).join('')}<li><i class="ch-sw ch-u" aria-hidden="true"></i><span>Сортировка, сборка троек, фото и листинг сверх бюджета</span><span class="hz">неизвестно</span></li></ul>`,
 'Строки базового сценария, лист 4. Заштрихованная часть — неизвестные статьи, сумм нет.')}
function figScen(){const mn=-617.58,mx=2057.81,span=mx-mn,z=(-mn/span*100);const bar=v=>{const l=v<0?(v-mn)/span*100:z,w=Math.abs(v)/span*100;return `<span class="ch-tr"><i class="ch-z" style="left:${z.toFixed(2)}%"></i><i class="ch-b${v<0?' ch-neg':''}" style="left:${l.toFixed(2)}%;width:${w.toFixed(2)}%"></i></span>`};
 const V=[['Прибыль по проданному',2],['Деньги на конец 90 дней',3],['Экономический результат',4]];
 return fig('Сценарии в трёх представлениях','£ · основание: исторический расчёт 30.09.2026, все входы — допущения',
 `<div class="ch-rows">${SC.map(s=>`<div class="ch-g"><p class="ch-gn"><b>${s[0]}</b> <span class="t2">${s[1]}</span></p>${V.map(v=>`<div class="ch-r"><span class="ch-n">${v[0]}</span>${bar(s[v[1]])}<span class="ch-v">${gb(s[v[1]])}</span></div>`).join('')}</div>`).join('')}</div>`,
 'Представления не складываются. Остаток в «деньгах» не учтён, в «прибыли по проданному» — по себестоимости. Цена ликвидации неизвестна.')}
function figSens(){const mn=-312.53,mx=725.31,span=mx-mn,z=-mn/span*100;const bar=v=>{const l=v<0?(v-mn)/span*100:z,w=Math.abs(v)/span*100;return `<span class="ch-tr"><i class="ch-z" style="left:${z.toFixed(2)}%"></i><i class="ch-b${v<0?' ch-neg':''}" style="left:${l.toFixed(2)}%;width:${w.toFixed(2)}%"></i></span>`};
 return fig('Чувствительность','£ · экономический результат и деньги на конец 90 дней · строки листа 4',
 `<div class="ch-rows">${SENS.map(s=>`<div class="ch-g"><p class="ch-gn">${esc(s[0])}</p><div class="ch-r"><span class="ch-n">Экон. результат</span>${bar(s[1])}<span class="ch-v">${gb(s[1])}</span></div><div class="ch-r"><span class="ch-n">Деньги</span>${bar(s[2])}<span class="ch-v">${gb(s[2])}</span></div></div>`).join('')}</div>`,
 'Запаса почти нет: 400 троек по £15.25 оставляют £6.56. Безубыточность — 344 тройки (на допущениях).')}
function figRest(){return fig('Непроданный остаток по сценариям','штук и £ по себестоимости £1.41 за шт. · основание: ev-10, на допущениях',
 `<div class="ch-rows">${SC.map(s=>`<div class="ch-r ch-r2"><span class="ch-n">${s[0]}</span><span class="ch-tr"><i class="ch-b ch-st" style="left:0;width:${(s[5]/600*100).toFixed(2)}%"></i></span><span class="ch-v"><b class="n">${s[5]} шт.</b> · £${s[6]}</span><span class="ch-liq">ликвидация: <span class="hz">неизвестна</span></span></div>`).join('')}</div>`,
 'При 1 200 шт. в партии остатка в базовом сценарии нет, а 500 троек невозможны.')}
const fig=(q,m,body,cap)=>`<figure class="ch10"><figcaption><p class="ch-q">${q}</p><p class="t2">${m}</p></figcaption>${body}<p class="ch-cap t2">${cap}</p></figure>`;

