function result(c){if(c.hist)return resultCard(c);if(c.kind==='own')return '';
 const tbl=`<div class="r10-hist"><p class="r10-hk">Исторический условный сценарий, не прогноз</p><p class="t2">Все входы — допущения (приложение B), итоги — рассчитано на допущениях. GBP, до пенса.</p><div class="tbl-wrap" tabindex="0" role="region" aria-label="Три сценария в трёх представлениях"><table class="tbl r10-t r10-num"><thead><tr><th scope="col">Сценарий</th><th scope="col" class="num">Прибыль по проданному</th><th scope="col" class="num">Деньги на конец 90 дней</th><th scope="col" class="num">Экономический результат</th><th scope="col" class="num">Остаток</th></tr></thead><tbody>${SC.map(s=>`<tr><th scope="row">${s[0]} <span class="t2">${s[1]}</span></th><td class="num">${gb(s[2])}</td><td class="num">${gb(s[3])}</td><td class="num">${gb(s[4])}</td><td class="num"><span class="n">${s[5]} шт. · £${s[6]}</span></td></tr>`).join('')}</tbody></table></div><div class="r10-scm">${SC.map(s=>`<section class="r10-scb" aria-label="${s[0]}: ${s[1]}"><p><b>${s[0]}</b> <span class="t2">${s[1]}</span></p><dl><div><dt>Прибыль по проданному</dt><dd>${gb(s[2])}</dd></div><div><dt>Деньги на конец 90 дней</dt><dd>${gb(s[3])}</dd></div><div><dt>Экономический результат</dt><dd>${gb(s[4])}</dd></div><div><dt>Остаток</dt><dd><span class="n">${s[5]} шт. · £${s[6]}</span></dd></div></dl></section>`).join('')}</div><p class="t2">Прибыль по проданному — до резерва претензий, налога и времени. Деньги — партия оплачена целиком. Экономический результат — после времени владельца £150.</p></div>`;
 const more=[['why','Почему такой вывод','G01–G10 · правила R1–R6',why()],['basis','Основания','приложение A · ev-01…ev-12',apxA()],['ass','Допущения','приложение B · a1–a10',apxB()],['plan','План действий','5 шагов · черновики не отправлены',plan()]].map(([k,t,s,b])=>`<section>${LP.acc('r10'+k,`<span class="sq">${t}</span><span class="tot">${s}</span>`,b)}</section>`).join('');
 return `<div class="r10-res">
<section class="r10-v" aria-labelledby="v10-h"><p class="eyebrow">1 · Вывод</p><h2 class="r10-vt" id="v10-h" tabindex="-1">Не покупать сейчас — нужны данные</h2><p class="r10-vs">Подтверждённых стоп-факторов нет — это не отказ. ${NOT_BUY.replace('Оплата исследования','Вывод')}</p><p class="t2"><span class="code">NEEDS_EVIDENCE</span> · отчёт <span class="code">${TD.rep}</span> v1 · ${TD.date}</p></section>
<section aria-labelledby="v10-r"><p class="eyebrow" id="v10-r">2 · Три причины</p><ol class="r10-why"><li><span>${gt('G01','unk')}</span><div><b>Состав и количество партии не подтверждены</b><p class="t2">Размеры и дизайны неизвестны. Страница продавца — 1 500 шт., поисковый фрагмент — 1 200 шт.; при проверке страница ответила 403 и не прочитана.</p></div></li><li><span>${gt('G03','unk')}</span><div><b>400 продаж троек по £16.95 — допущение</b><p class="t2">Найдены только активные предложения других наборов. Состоявшихся продаж сопоставимых троек нет.</p></div></li><li><span>${gt('G04','unk')}</span><div><b>Нет полной котировки склада</b><p class="t2">Сортировка, сборка троек, фото и листинг не оценены; есть только публичный прайс отдельных операций.</p></div></li></ol></section>
<section class="r10-eco" aria-labelledby="v10-e"><p class="eyebrow" id="v10-e">3 · Ключевая экономика</p>
<div class="r10-k3"><div class="r10-kb"><h3 class="h3">Предел закупки</h3><dl class="r10-kv2"><div><dt>Максимальная цена</dt><dd>${UNK('не определена')}</dd></div><div><dt>Объём</dt><dd>${UNK('не определён')}</dd></div></dl><p class="t2">Нужны состав, три статьи затрат, подтверждённая выручка, ваша цель и предел убытка; лот продаётся целиком, количество спорно.</p></div>
<div class="r10-kb"><h3 class="h3">Полная стоимость</h3><dl class="r10-kv2"><div><dt>Закупка до продаж, не меньше</dt><dd>${gb(1665)} ${kk('ass')}</dd></div><div><dt>С подготовкой и фото до продаж</dt><dd>${gb(2265)} ${kk('ass')}</dd></div></dl><div class="r10-fc" role="img" aria-label="Известная часть £2 265.00, недостающие статьи без суммы"><i style="flex:1665"></i><i style="flex:600" class="r10-fc2"></i><i class="r10-fc3"></i></div><p class="t2">Не хватает: сортировка, сборка троек, фото и листинг — заштрихованы, суммы нет. Цена — со страницы продавца, бюджет — без котировок.</p></div>
<div class="r10-kb"><h3 class="h3">Прибыль и деньги</h3><dl class="r10-kv2"><div><dt>Прибыль</dt><dd>${UNK('не определена')}</dd></div><div><dt>Пиковая потребность в деньгах</dt><dd>${UNK('не определена')}</dd></div></dl></div></div>
${tbl}
<div class="r10-ch">${figCost()}${figScen()}${figSens()}${figRest()}</div>
<p class="r10-nocash t2">Движения денег по неделям в материалах нет — такой график не строится.</p></section>
<section class="r10-adv" aria-labelledby="v10-a"><p class="eyebrow" id="v10-a">4 · Неблагоприятный случай: 300 троек по £15.25</p><dl class="r10-kv2 r10-advl"><div><dt>Деньги на конец 90 дней</dt><dd>${gb(-467.58)}</dd></div><div><dt>Экономический результат</dt><dd>${gb(-617.58)}</dd></div><div><dt>Остаток 600 шт. по себестоимости</dt><dd>${gb(846)}</dd></div><div><dt>Цена ликвидации остатка</dt><dd>${UNK('неизвестна')}</dd></div></dl><p class="t2">Рассчитано на допущениях. Прибыль по проданному +£687.56, а денег −£467.58: 600 футболок на складе.</p></section>
<div class="r10-g2"><section aria-labelledby="v10-m"><p class="eyebrow" id="v10-m">5 · Чего не хватает</p><ul class="r10-miss">${MISS.map(m=>`<li><span class="ms u" aria-hidden="true"></span><span>${m[0]}</span><span class="t2">${m[1]}</span></li>`).join('')}</ul></section>
<section aria-labelledby="v10-c"><p class="eyebrow" id="v10-c">Что изменит вывод</p><ul class="r10-chg">${CHANGE.map(x=>`<li><span>${esc(x[0])}</span><span class="t2">→ ${esc(x[1])}</span></li>`).join('')}</ul></section></div>
<div class="r10-g2"><section aria-labelledby="v10-n"><p class="eyebrow" id="v10-n">6 · Следующий шаг</p><p>Отправить подготовленные запросы продавцу и складу, выгрузить продажи сопоставимых троек на eBay, задать пределы — затем обновить исследование.</p><a class="lnk" href="#acc-r10plan" data-act="r10-plan">Открыть план и черновики</a></section>
<section aria-labelledby="v10-u"><p class="eyebrow" id="v10-u">7 · Действует до</p><p><b class="n">${TD.until}</b> <span class="t2">— раньше всего истекает тариф eBay (7 дней). Скачанный PDF не обновляется.</span></p></section></div>
<div class="r10-docs"><a class="btn btn-s" href="#/research/${c.id}/docs">Документы · отчёт 9 листов, меморандум 2 листа</a><a class="lnk" href="#/research/${c.id}/letters">Письма</a></div>
<div class="u2 r10-more">${more}</div></div>`}
function why(){return `<div class="tbl-wrap" tabindex="0" role="region" aria-label="Проверки G01–G10"><table class="tbl r10-t"><thead><tr><th scope="col">Проверка</th><th scope="col">Результат</th><th scope="col">Почему</th><th scope="col">Что закроет</th></tr></thead><tbody>${Object.keys(GN).map(g=>`<tr><th scope="row">${GN[g]} <span class="code">${g}</span></th><td>${g==='G10'?gt(g,'pass')+'<span class="t2"> машинная · человек не запрашивается</span>':gt(g,g==='G09'?'pass':'unk')}</td><td>${esc(GTXT[g][0])}</td><td class="t2">${esc(GTXT[g][1])}</td></tr>`).join('')}</tbody></table></div>
<h3 class="h3">Как получено действие</h3><ul class="r10-rl">${RULES.map(r=>`<li><span class="code">${r[0]}</span><span>${esc(r[1])}</span></li>`).join('')}</ul>
<details class="r10-x r10-codes"><summary>Коды для сверки</summary><p class="t2"><span class="code">NEEDS_EVIDENCE</span> · доказательства <span class="code">CONFLICTED</span> · экономика <span class="code">UNDETERMINED</span>, основание <span class="code">CONDITIONAL</span> · покрытие <span class="code">SUPPORTED</span> · правило <span class="code">R6</span> · <span class="code">research-decision/1</span></p></details>`}
function apxA(){return `<p class="t2">Недоступная страница не выдаётся за прочитанную; поисковый фрагмент не закрывает ни одного существенного поля; активное объявление не доказывает продажи.</p><div class="tbl-wrap" tabindex="0" role="region" aria-label="Основания"><table class="tbl r10-t"><thead><tr><th scope="col">ID</th><th scope="col">Источник</th><th scope="col">Получено</th><th scope="col">Вид знания</th><th scope="col">Что подтверждает и чего нет</th></tr></thead><tbody>${APXA.map(a=>`<tr><td class="code">${a[0]}</td><th scope="row">${esc(a[1])}</th><td class="t2">${esc(a[2])}</td><td>${kk(a[3],a[4])}</td><td>${esc(a[5])}</td></tr>`).join('')}</tbody></table></div>`}
function apxB(){return `<p class="t2">Каждое допущение — вход сценариев. Ни одно не подтверждено.</p><div class="tbl-wrap" tabindex="0" role="region" aria-label="Допущения"><table class="tbl r10-t"><thead><tr><th scope="col">#</th><th scope="col">Допущение</th><th scope="col">Чем заменить</th></tr></thead><tbody>${APXB.map(a=>`<tr><td class="code">${a[0]}</td><td>${esc(a[1])}</td><td class="t2">${esc(a[2])}</td></tr>`).join('')}</tbody></table></div>`}
function plan(){return `<p class="t2">Исследование ничего не отправляет, не регистрирует и не покупает. Предел закупочной цены в запросы не включается.</p><ol class="r10-plan">${PLAN.map((p,i)=>`<li><div class="r10-plh"><span class="n">${i+1}</span><b>${p[0]}</b><span class="t2">${p[1]}</span><span class="code">${p[3]}</span><span class="tag">${p[4]}</span></div>${p[5]?`<details class="r10-x"><summary>Черновик · подготовлен, не отправлен</summary><p class="r10-draft" id="dr10-${i}">${esc(p[2])}</p><button type="button" class="btn btn-s sm" data-act="r10-copy" data-i="${i}">Скопировать текст</button></details>`:`<p class="t2">${esc(p[2])}</p>`}</li>`).join('')}</ol>`}
function resultCard(c){const res=P9().res;if(!res)return '';const x=res({sk:c.sk,f:null,qa:c.qa||null});if(!x)return '';const GNs=Object.values(GN);
 const km=(l,k)=>/^Закупка/.test(l)&&k!=='unk'?'seller':k;
 return `<div class="r10-res"><section class="r10-v" aria-labelledby="v10-h"><p class="eyebrow">Вывод</p><h2 class="r10-vt" id="v10-h" tabindex="-1">Не покупать сейчас — нужны данные</h2><p class="r10-vs">Подтверждённых стоп-факторов нет — это не отказ.${x.partial?' Результат частичный.':''}</p><p class="t2">Вывод карточки не становится выводом исследования; результат не перезаписывает ваше решение.</p></section>
<section><p class="eyebrow">Три причины</p><ol class="r10-why">${x.why.map(w=>{const g='G'+pad(w[0]);return `<li><span>${gt(g,'unk')}</span><div><b>${GNs[w[0]-1]}</b><p class="t2">${esc(w[1])}</p></div></li>`}).join('')}</ol></section>
<section class="r10-eco"><p class="eyebrow">Ключевая экономика</p><dl class="r10-kv2">${x.money.map(m=>`<div><dt>${esc(m[0])}</dt><dd>${m[1]==='неизвестно'?UNK('неизвестно'):'<span class="n">'+esc(m[1])+'</span>'} ${kk(km(m[0],m[2]))}<span class="t2"> ${esc(m[3])}</span></dd></div>`).join('')}</dl><p class="t2">${esc(x.limit)}</p></section>
<section class="r10-adv"><p class="eyebrow">Неблагоприятный случай</p><p>${esc(x.adverse)}</p></section>
<div class="r10-g2"><section><p class="eyebrow">Чего не хватает</p><ul class="r10-miss">${x.miss.map(m=>`<li><span class="ms u" aria-hidden="true"></span><span>${esc(m)}</span></li>`).join('')}</ul></section><section><p class="eyebrow">Что изменит вывод</p><ul class="r10-chg">${x.change.map(y=>`<li><span>${esc(y[0])}</span><span class="t2">→ ${esc(y[1])}</span></li>`).join('')}</ul></section></div>
<div class="r10-g2"><section><p class="eyebrow">Следующий шаг</p><ul class="r10-ul">${x.next.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section><p class="eyebrow">Действует до</p><p>${x.until==='не задано'?'срок действия не задан':'<b class="n">'+esc(x.until)+'</b>'} <span class="t2">· ${esc(x.untilWhy)}</span></p></section></div>
<p class="r10-note">Покрытие amazon.de — только исследование. Документ в демо не собран; формат — как у <span class="code">${TD.rep}</span>.</p>
<div class="u2 r10-more"><section>${LP.acc('r10c'+c.id,'<span class="sq">Основания</span><span class="tot">'+x.src.length+' источника</span>',`<ul class="r10-ul">${x.src.map(s=>`<li><b>${esc(s[0])}</b> <span class="t2">· ${esc(s[1])} · ${esc(s[2])} · ${esc(s[3])}</span></li>`).join('')}</ul>`)}</section></div></div>`}

/* ══ документы и письма ══ */
const DOCS=[{id:'report',t:'Полный отчёт',code:TD.rep+' v1',fmt:'9 листов A4 · PDF + в кабинете',file:'cto/report.html'},{id:'memo',t:'Меморандум «Краткое решение»',code:TD.memo+' v1',fmt:'2 листа A4 · лист 2 — вариант «отказ или недостаточность данных»',file:'cto/memo.html'}];
function docs(c,q){if(!isTD(c)||c.stage!=='result')return `<p class="t2">${c.kind==='card'?'Документ в демо не собран; формат — как у '+TD.rep+'.':'Документов пока нет: они появятся после результата.'}</p>`;
 const open=q.get('doc');const l2=c.mail.l2;const d=DOCS.find(x=>x.id===open);
 return `<div class="r10-docl"><h2 class="h2" id="d10-h" tabindex="-1">Кабинет: документы</h2><p class="t2">Кабинет, PDF и вложение письма — одна версия. Сверка: <b>«Не покупать сейчас — нужны данные»</b> · закупка <span class="n">£1 665.00</span> · неблагоприятно <span class="n">−£467.58</span> и <span class="n">−£617.58</span> · <span class="n">£413.29</span> — только условный сценарий · до <span class="n">${TD.until}</span>.</p>
${ST.prof==='paid'?'<p class="r10-note">Вы прошли платный путь (демо, £79 по гипотезе C3). Документ кейса исторический: на листе 4 указано «£0 (профиль Founder)».</p>':''}
<ul class="r10-dl">${DOCS.map(x=>`<li><div><p><b>${x.t}</b> <span class="code">${x.code}</span></p><p class="t2">${x.fmt} · ${TD.date} · действует до ${TD.until}</p></div><div class="r10-da"><a class="btn btn-s sm" href="#/research/${c.id}/docs?doc=${x.id}" id="d10-v-${x.id}"${open===x.id?' aria-current="true"':''}>Смотреть</a><button type="button" class="btn btn-s sm" data-act="d10-pdf" data-doc="${x.id}">Скачать PDF</button><a class="lnk" href="${x.file}" target="_blank" rel="noopener">Открыть отдельно<span class="sr-only"> (новая вкладка)</span></a></div></li>`).join('')}
<li class="r10-dlx"><div><p><b>Инвестиционный меморандум</b> <span class="tag">формат описан, макета нет</span></p><p class="t2">4–6 листов A4 · строится только по опубликованному отчёту · для партнёра или соинвестора</p></div><details class="r10-x"><summary>Разделы</summary><ol class="r10-ol2">${INV.map(x=>`<li><b>${x[0]}</b> <span class="t2">${x[1]}</span></li>`).join('')}</ol></details></li>
<li class="r10-dlx"><div><p><b>Обновление исследования</b> <span class="tag">формат описан, макета нет</span></p><p class="t2">1–2 листа A4 · строится из разницы двух версий: было LPR-… vN → стало vN+1</p></div><details class="r10-x"><summary>Разделы</summary><ol class="r10-ol2">${UPD.map(x=>`<li><b>${x[0]}</b> <span class="t2">${x[1]}</span></li>`).join('')}</ol></details></li></ul>
<p class="t2">Скачать PDF: в демо PDF формируется печатью браузера — выберите «Сохранить как PDF».</p>
<section class="r10-ml" aria-labelledby="d10-m"><h3 class="h3" id="d10-m">Письмо «Отчёт готов»</h3><p>${l2.st==='bounce'?`<span class="st10" data-s="bounce"><i aria-hidden="true"></i>Не доставлено</span> на ${esc(c.email)}`:l2.st==='sent'?`<span class="st10" data-s="sent"><i aria-hidden="true"></i>Отправлено</span> на ${esc(c.email)} · ${esc(l2.at||'')}`:'<span class="st10" data-s="ready"><i aria-hidden="true"></i>Отчёт готов, письмо не отправлялось</span>'} <span class="t2">· «отправлено» не значит «получено»</span></p>${l2.log.length?`<ul class="r10-ul">${l2.log.map(t=>`<li class="n">${esc(t)}</li>`).join('')}</ul>`:''}
${l2.st==='bounce'?`<form id="d10-fix" class="r10-mail" novalidate><label class="h3" for="d10-em">Исправьте адрес</label><div class="r10-cap"><input id="d10-em" name="email" type="email" value="${esc(c.email)}" aria-describedby="d10-emh"><button class="btn btn-p sm" type="submit">Отправить снова (демо)</button></div><p class="t2" id="d10-emh">${emailHint(c.email)}</p></form>`:`<button type="button" class="btn btn-s sm" data-act="d10-resend">Отправить письмо повторно (демо)</button>`}
<a class="lnk" href="#/research/${c.id}/letters">Посмотреть письма</a></section>
${d?`<section class="r10-view" aria-labelledby="d10-vh"><div class="r10-vb"><h3 class="h3" id="d10-vh" tabindex="-1">${d.t} · ${d.code}</h3><a class="lnk" href="#/research/${c.id}/docs">Закрыть</a></div><iframe id="d10-frame" src="${d.file}" title="${d.t} ${d.code}"></iframe></section>`:''}</div>`}
const INV=[['Что рассматриваем','предмет, рынок, каналы, роль, объём, горизонт'],['Решение и три причины','обязательна фраза «не разрешение на закупку и не инвестиционная рекомендация»'],['Сумма и предел','сумма закупки, предел цены, предельный объём, пиковая потребность в деньгах; предел цены печатается только с согласия, иначе «не раскрывается»'],['Прибыль, деньги, риск','три представления, полный проект и «с текущего момента», окупаемость, безубыточность; условные числа — только в рамке «условный сценарий»'],['Контрсценарий','неблагоприятный и ликвидация, пороги, при которых результат становится отрицательным'],['Расчёт','входы с видом знания и источником, формулы статей, версия расчёта; неизвестное штрихуется, не ноль'],['Источники','вид, когда получено, статус получения, что подтверждает'],['Приложения','допущения и чем их заменить, противоречия, версии, ссылка проверки'],['Срок действия','']];
const UPD=[['Что рассматриваем','ссылки «было → стало»'],['Решение','было → стало'],['Что изменилось','каждое поле, было/стало, вид знания было/стало, новое основание; новые и разрешённые противоречия; истёкшие основания'],['Влияние на деньги','базовый и неблагоприятный сценарии в каждом представлении, предел цены, пиковая потребность — было → стало → разница; разница — только когда оба значения определены'],['Какие проверки повторены','G01–G10 было → стало; без изменений — одной строкой'],['Оставшиеся условия, которые изменят вывод',''],['Срок действия','прежний документ становится «заменён новой версией»']];
function letters(c){if(!isTD(c)||c.stage==='setup'||c.ord.st!=='paid')return '<p class="t2">Писем пока нет: подтверждение приходит после оплаты.</p>';const paid=ST.prof==='paid',l2=c.mail.l2,rd=c.stage==='result';
 const hd=(subj,pre,to)=>`<div class="lt-env"><p><span class="t2">Тема</span> <b>${subj}</b></p><p><span class="t2">Кому</span> ${esc(to)}</p><p class="t2">${pre}</p></div>`;
 const brand=`<div class="lt-lh"><img src="../assets/logo-light.svg" alt="LotPrism" width="132" height="17"><span>Research</span></div>`;
 return `<div class="r10-lts"><h2 class="h2" id="l10-h" tabindex="-1">Письма</h2><p class="t2">Макеты. Почтовой отправки в продукте нет. Подтверждение заказа и готовый отчёт — разные сообщения.</p>
<section class="lt10" aria-label="Письмо 1: подтверждение заказа"><p class="lt-st"><span class="st10" data-s="sent"><i aria-hidden="true"></i>Отправлено ${esc(c.ord.at||'')}</span></p><p class="t2">Номер заказа ${TD.order} — пример формата.</p>${hd('LotPrism · заказ '+TD.order+' подтверждён: '+TD.short,'Исследование начато. О готовом отчёте придёт отдельное письмо.',c.email)}
<article class="lt-b">${brand}<h3>Заказ ${TD.order} подтверждён</h3><p class="t2">номер — пример формата</p><dl><div><dt>Предмет</dt><dd>${TD.title}</dd></div><div><dt>Рынок</dt><dd>GB · eBay UK · GBP · горизонт 90 дней</dd></div><div><dt>Исследование</dt><dd>полное исследование партии · C3</dd></div><div><dt>Оплата</dt><dd>${paid?'£79 — демо, деньги не списаны; гипотеза пилотного тарифа, не действующая цена':'£0 — профиль Founder, этапы S0–S2'}</dd></div></dl><p><b>Что дальше.</b> Исследование идёт. Если понадобится уточнение, спросим в кабинете. Готовый отчёт придёт отдельным письмом и будет доступен в кабинете независимо от доставки.</p><p class="lt-f">${NOT_BUY} LotPrism ничего не покупает и не отправляет от вашего имени.</p></article></section>
<section class="lt10" aria-label="Письмо 2: отчёт готов"><p class="lt-st">${!rd?'<span class="st10" data-s="draft"><i aria-hidden="true"></i>Ещё не отправлено — отчёт не готов</span>':l2.st==='bounce'?'<span class="st10" data-s="bounce"><i aria-hidden="true"></i>Не доставлено</span> <a href="#/research/'+c.id+'/docs">Исправить адрес</a>':l2.st==='sent'?'<span class="st10" data-s="sent"><i aria-hidden="true"></i>Отправлено '+esc(l2.at||'')+'</span>':'<span class="st10" data-s="ready"><i aria-hidden="true"></i>Не отправлялось</span>'}</p>${hd('LotPrism · отчёт готов: '+TD.short,'Не покупать сейчас — нужны данные. Действует до '+TD.until+'.',c.email)}
<article class="lt-b">${brand}<h3>Отчёт готов: ${TD.short}</h3><p class="lt-v"><b>Не покупать сейчас — нужны данные:</b> состав и количество партии, спрос и затраты склада не подтверждены. Это не разрешение на закупку.</p><p class="lt-att"><span class="lt-pdf" aria-hidden="true">PDF</span><span><b>${TD.pdf}</b><span class="t2">полный отчёт · 9 листов A4 · v1 · ${TD.date}</span></span></p><p><a class="lt-btn" href="#/research/${c.id}?s=result">Открыть в LotPrism</a></p><p>Действует до <b>${TD.until}</b>. Скачанный PDF не обновляется — актуальность проверяйте в LotPrism.</p><p class="lt-f">Не инвестиционная рекомендация и не разрешение на закупку.</p></article></section></div>`}

/* ══ страница дела ══ */
function casePage(c,view,q){const body=view==='setup'?setup(c):view==='order'?order(c):view==='work'?work(c):view==='result'?result(c):view==='docs'?docs(c,q):letters(c);
 return `<main class="main r10" data-screen-label="Research ${c.id} · ${view}">${caseHead(c,view)}<div id="cb10">${body}</div></main>`}
const defView=c=>c.hist?(c.run.st==='done'?'result':'work'):c.stage;

/* ══ выполнение (демо) ══ */
let tmr=0;
function startRun(c){c.run.st='run';c.stage='work';save();arm()}
function arm(){clearTimeout(tmr);const c=CS(TD.id);if(!c||c.run.st!=='run')return;tmr=setTimeout(tick,RM()?450:1300)}
function tick(){const c=CS(TD.id);if(!c||c.run.st!=='run')return;c.run.i=(c.run.i||0)+1;const s=EV[c.run.i-1];
 if(s&&s.pause&&!c.run.q){c.run.st='input';c.run.askedIso=todayIso();ev('Требуется уточнение: количество 1 500 или 1 200','#/research/'+c.id+'?s=work',c.id);say('Требуется уточнение: количество. Ответьте на вопрос исследования')}
 if(c.run.i>=EV.length){finish(c)}save();repaintWork();arm()}
function finish(c){c.run.st='done';c.run.i=EV.length;c.stage='result';const t=nowT();ev('Отчёт готов: '+TD.short,'#/research/'+c.id+'?s=result',c.id);c.mail.l2={st:'sent',at:t,log:['отправлено '+t]};ev('Письмо «Отчёт готов» отправлено на '+c.email,'#/research/'+c.id+'/letters',c.id);say('Результат готов. Отчёт в кабинете')}
function repaintWork(){const r=LP.parse();const m=r.p.match(/^\/research\/(R-[A-Z0-9-]+)$/);if(!m||m[1]!==TD.id)return;const c=CS(TD.id);const v=r.q.get('s')||defView(c);if(v!=='work'){render();return}
 const ae=document.activeElement,aid=ae&&ae.id;$('#cb10').innerHTML=T(work(c));const ln=$('.ln10');if(ln)ln.outerHTML=T(line(c,'work'));const ch=$('.r10-meta .st10');if(ch)ch.outerHTML=chip(c);LP.shell9&&0;
 if(aid&&document.getElementById(aid))document.getElementById(aid).focus({preventScroll:true});if(c.run.st==='input'){const h=$('#q10-h');h&&h.focus({preventScroll:true})}}

/* ══ маршрут ══ */
function render(){const r=LP.parse();LP.p10(r)}
LP.p10n=()=>Object.values(ST.cases).filter(c=>c.run&&c.run.st==='input').length;
LP.p10=function(r){const p=r.p;let m,html=null,focus='#view h1';
 if(p==='/research'){html=home()}
 else if(p==='/research/new'){newFrom(r.q);return true}
 else if(m=p.match(/^\/research\/(R-[A-Z0-9-]+)(?:\/(docs|letters))?$/)){let c=CS(m[1]);if(!c&&m[1]===TD.id)c=tdDone();
  if(!c)html=`<main class="main r10"><h1 class="h1">Исследование не найдено</h1><p class="t2">Возможно, демо Research сброшено.</p><a href="#/research">← Research</a></main>`;
  else{let v=m[2]||r.q.get('s')||defView(c);if(!c.hist&&(v==='result'||v==='work')&&!(c.kind==='td'&&c.ord.st==='paid'))v=c.stage;if(v==='result'&&c.kind==='td'&&c.stage!=='result')v=c.stage;if(v==='work'&&c.kind==='td'&&c.ord.st!=='paid')v=c.stage;html=casePage(c,v,r.q);
   focus=r.q.get('doc')?'#d10-vh':'#view h1'}}
 else return false;
 $('#view').innerHTML=T(html);proto10();
 const key=location.hash;if(LP._p10last!==key){LP._p10last=key;scrollTo(0,0);const h=$(focus);if(h){h.tabIndex=-1;h.focus({preventScroll:true})}}
 return true};
function tdDone(){const c=tdNew(true);Object.assign(c,{shown:1,stage:'result',ord:{st:'paid',at:'30.09.2026'},run:{i:EV.length,st:'done'},at:'2026-09-30'});c.mail.l1={at:'30.09.2026'};c.mail.l2={st:'sent',at:'30.09.2026',log:['отправлено 30.09.2026']};ST.prof='founder';save();return c}
function newFrom(q){const subj=q.get('subj'),id=q.get('id'),from=q.get('from')||'';
 if(subj&&id){const sk=(subj==='lot'?'lot:':subj==='hyp'?'hyp:':'item:')+id;const sj=(P9().DEMO||{subj:{}}).subj[sk];
  const cid='R-N'+(++ST.n);ST.cases[cid]={id:cid,kind:sj?'card':'own',sk,task:'check',sub:subj==='lot'?'mixed':'single',url:'',ident:id,text:'',files:[],goal:'resale',mk:'DE',ch:['amazon.de'],chNeed:subj==='lot',cap:'',capNone:true,hor:'90',horOwn:'',depth:'full',email:'irina.becker@demo-handel.example',step:1,stage:'setup',ord:{st:'draft'},run:{st:'idle'},mail:{l1:null,l2:{st:'none',log:[]}},at:todayIso(),from};
  if(sj)ST.cases[cid].kind='card',ST.cases[cid].fresh=1;save();location.replace('#/research/'+cid);return}
 location.replace('#/research')}

