 't10-restart':()=>{clearTimeout(tmr);delete ST.cases[TD.id];ST.ev=ST.ev.filter(e=>e.id!==TD.id);save();location.hash='#/research';setTimeout(()=>{const t=$('#f10-text');if(t){t.value=EXAMPLE;t.focus()}},60)},
